interface Box<T> { value: T }
type Alias<T = string> = { value: T };
type Conditional<T> = T extends string ? Box<T> : Box<number>;
function generic<T>() {
 let object1!: Box<T>; let object2!: Box<T>;
 let alias1!: Alias<T>; let alias2!: Alias<T>;
 let conditional1!: Conditional<T>; let conditional2!: Conditional<T>;
 let indexed1!: T[keyof T]; let indexed2!: T[keyof T];
}
declare let explicit: Alias<string>;
declare let defaulted: Alias;

const result = Array.from(1);
const combined = Array.from;
const subsequent = [1, 2].map(x => x + 1);

declare function use<T>(x: { make: () => T; take: (value: T) => void }): T;
const failed = use({ make: () => 1, take: value => value.notPresent() });
const subsequent = use({ make: () => "text", take: value => value.toUpperCase() });

declare const f: <T>(f: (x: T) => unknown) => (x: T) => unknown;
declare const g: <T extends unknown>(x: { foo: T }) => unknown;
const h = f(g);
type FirstParameter<T> = T extends (x: infer P) => unknown ? P : unknown;
type X = FirstParameter<typeof h>["foo"];
declare let result: X;

type Box<T> = { value: T };
type Mapped<T> = { [K in keyof T]: Box<T[K]> };
declare function unwrap<T>(x: Mapped<T>): T;
const object = unwrap({ left: { value: "x" }, right: { value: 42 } });
declare const boxedArray: Box<number>[];
const array = unwrap(boxedArray);
const tuple = unwrap([{ value: "x" }, { value: "y" }]);
const subsequent = Promise.resolve(object.right);

type Deep<T> = T extends unknown ? 1 | Deep<[T]> : never;
type X = Deep<string>;
declare let result: X;
const subsequent = 1;

type Event<T> = { callback: (arg: T) => void; nested: { nestedCallback: (arg: T) => void } };
declare function emit<T>(key: T, value: Event<T>): void;
const cached = emit("a", { callback: r => {}, nested: { nestedCallback: r => { const nestedResult = r; } } });
